def f(n):
    """
    Calculates f(n), the odd part of n.
    f(n) = n / 2^m, where m is the exponent of 2 in the prime factorization of n.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(u, v):
    """
    Checks if f(n+v) - f(n) is a multiple of 4 for all n in [u, u+v-1].
    """
    for n in range(u, u + v):
        diff = f(n + v) - f(n)
        if diff % 4 != 0:
            return False
    return True

